using System;
using System.IO;
using System.Collections.Generic;
using UnityEngine;
using UnityEngine.EventSystems;
using UnityEngine.UI;
using UnityEditor;
using CampaignDemo;
[InitializeOnLoad]
public static class MinimapRuntimeVerification {
 static double start;static int stage;static readonly List<string> results=new List<string>();
 static MinimapRuntimeVerification(){if(SessionState.GetBool("MinimapRuntime",false)){start=EditorApplication.timeSinceStartup;EditorApplication.update+=Poll;}}
 public static void Run(){MinimapInstaller.Run();SessionState.SetBool("MinimapRuntime",true);start=EditorApplication.timeSinceStartup;EditorApplication.update+=Poll;EditorApplication.isPlaying=true;}
 static void Check(bool ok,string label){if(!ok)throw new Exception(label);results.Add("PASS "+label);}
 static void Poll(){try{
  if(EditorApplication.timeSinceStartup-start>90)throw new Exception("minimap runtime timeout");if(!EditorApplication.isPlaying||Time.time<1)return;var minimap=UnityEngine.Object.FindObjectOfType<TacticalMinimap>();var world=minimap.world;if(world==null||!world.Initialized)return;var hud=minimap.GetComponent<CampaignHUD>();
  if(stage==0){world.setup.modes.EnterInspectionMode();foreach(var army in world.units)if(army!=null&&army.OnMap&&army.ownerId==world.currentPlayer){hud.SelectUnit(army);break;}minimap.Render();Canvas.ForceUpdateCanvases();Check(Mathf.Abs(minimap.Window.rect.width-minimap.Window.rect.height)<.01f,"square minimap");Check(hud.uiFontSize==13&&hud.rightPanelWidth==280,"compact mode 3 typography and width");Check(Mathf.Abs(hud.RightPanel.offsetMax.y+minimap.ReservedTop)<.01f,"panel reserves square minimap space");
   Check(minimap.showControlGrid,"ownership grid enabled");Check(minimap.viewportColor==Color.yellow,"viewport border yellow");foreach(var city in world.points)if(city!=null&&city.kind==FacilityKind.RecoveryPoint)Check(city.minimapMajorCity,"existing cities configured as major landmarks");VerifyControl(minimap,world);VerifyFog(minimap,world);var raw=minimap.Window.GetComponent<RawImage>();Check(raw.texture!=null,"terrain minimap texture generated");Check(raw.raycastTarget,"map input intercepted by UI");var original=world.setup.mapCamera.transform.position;var center=RectTransformUtility.WorldToScreenPoint(null,minimap.Window.TransformPoint(minimap.Window.rect.center));minimap.OnPointerClick(new PointerEventData(EventSystem.current){position=center,button=PointerEventData.InputButton.Left});var expected=minimap.MapToWorld(Vector2.one*.5f);Check(Vector2.Distance(world.setup.mapCamera.transform.position,expected)<.01f,"minimap click moves main camera");Check(world.setup.mapCamera.transform.position.z==original.z,"camera depth preserved");minimap.SetExpanded(false);Check(!minimap.expanded,"collapse starts rightward slide");stage=1;return;
  }
  if(stage==1){if(minimap.Window.gameObject.activeSelf||Mathf.Abs(hud.RightPanel.offsetMax.y+minimap.margin)>.01f)return;Check(!minimap.Window.gameObject.activeSelf,"completed slide hides minimap");Check(minimap.TabVisibleFor(new Vector2(Screen.width-1,0)),"right screen edge reveals reopen tab");Check(!minimap.TabVisibleFor(new Vector2(-100,-100)),"reopen tab hidden away from right edge");Check(Mathf.Abs(hud.RightPanel.offsetMax.y+minimap.margin)<.01f,"collapsed map returns space to right panel");var buttons=minimap.GetComponentsInChildren<Button>(true);Button tab=null;foreach(var button in buttons)if(button.name=="Minimap collapse tab")tab=button;Check(tab!=null,"right edge reopen tab exists");tab.gameObject.SetActive(true);Capture(minimap.GetComponentInParent<Canvas>(),world,"minimap-collapsed-preview.png");tab.onClick.Invoke();Check(minimap.expanded&&minimap.Window.gameObject.activeSelf,"same small tab reopens map");stage=2;return;}
  if(stage==2){if(Mathf.Abs(minimap.Window.anchoredPosition.x+minimap.margin)>.01f)return;Canvas.ForceUpdateCanvases();Check(Mathf.Abs(hud.RightPanel.offsetMax.y+minimap.ReservedTop)<.01f,"expanded map restores panel reservation");world.setup.zoomController.SetSize(5);if(hud.SelectedUnit!=null){var pos=hud.SelectedUnit.transform.position;var camera=world.setup.mapCamera;camera.transform.position=new Vector3(pos.x,pos.y,camera.transform.position.z);}minimap.Render();Capture(minimap.GetComponentInParent<Canvas>(),world,"minimap-preview.png");File.WriteAllText("minimap-runtime-verification.txt",results.Count+" checks passed\n"+string.Join("\n",results));Debug.Log("MINIMAP_RUNTIME_VERIFIED "+results.Count);SessionState.SetBool("MinimapRuntime",false);EditorApplication.update-=Poll;EditorApplication.Exit(0);}
 }catch(Exception e){Debug.LogException(e);File.WriteAllText("minimap-runtime-verification.txt",e+"\n"+string.Join("\n",results));SessionState.SetBool("MinimapRuntime",false);EditorApplication.update-=Poll;EditorApplication.Exit(1);}}
 static void VerifyControl(TacticalMinimap minimap,BattleWorld world){world.territory.Resolve();minimap.showControlGrid=false;minimap.Render();var texture=(Texture2D)minimap.Window.GetComponent<RawImage>().texture;var original=texture.GetPixels();minimap.showControlGrid=true;minimap.Render();var overlay=texture.GetPixels();bool blue=false,red=false;for(int i=0;i<overlay.Length;i++){if(overlay[i]==original[i])continue;var c=overlay[i];if(c.b>c.r+.1f)blue=true;if(c.r>c.g+.1f&&c.r>c.b+.1f)red=true;}Check(blue,"actual friendly ownership pixels blue");Check(red,"actual enemy ownership pixels red with fog enabled");int count=0;foreach(var cell in world.territory.AllCells())count++;Check(count==world.territory.CellCount,"grid follows exact gameplay cell geometry");}
 static void VerifyFog(TacticalMinimap minimap,BattleWorld world){
  var map=world.setup.freeMarchMap;var rect=map.definition.bounds;Vector3 point=Vector3.zero;bool found=false;
  foreach(var uv in new[]{new Vector2(.1f,.1f),new Vector2(.9f,.1f),new Vector2(.1f,.9f),new Vector2(.9f,.9f)}){var candidate=map.transform.TransformPoint(new Vector3(rect.xMin+rect.width*uv.x,rect.yMin+rect.height*uv.y));if(!world.VisibleAt(world.currentPlayer,candidate)){point=candidate;found=true;break;}}
  Check(found,"test point outside friendly observation");var g=new GameObject("Hidden minimap test");g.transform.position=point;var unit=g.AddComponent<BattleUnit>();unit.unitId=Guid.NewGuid().ToString("N");unit.ownerId=world.currentPlayer=="A"?"B":"A";unit.combatDefinition=ScriptableObject.CreateInstance<ArmyCombatDefinition>();world.campaign.ConfigureUnit(unit);unit.Initialize();var originals=world.units;var all=new List<BattleUnit>(originals){unit};world.units=all.ToArray();bool fog=world.fogEnabled;world.fogEnabled=true;minimap.Render();Check(!HasRed(minimap,point),"hidden enemy not rendered on minimap");world.fogEnabled=false;minimap.Render();Check(HasRed(minimap,point),"visible enemy renders red marker");world.fogEnabled=fog;world.units=originals;UnityEngine.Object.DestroyImmediate(unit.combatDefinition);UnityEngine.Object.DestroyImmediate(g);minimap.Render();
 }
 static bool HasRed(TacticalMinimap minimap,Vector3 point){var texture=(Texture2D)minimap.Window.GetComponent<RawImage>().texture;var uv=minimap.WorldToMap(point);int cx=Mathf.RoundToInt(uv.x*(texture.width-1)),cy=Mathf.RoundToInt(uv.y*(texture.height-1));for(int y=cy-2;y<=cy+2;y++)for(int x=cx-2;x<=cx+2;x++)if(x>=0&&y>=0&&x<texture.width&&y<texture.height){var color=texture.GetPixel(x,y);if(color.r>.95f&&color.g<.05f&&color.b<.05f)return true;}return false;}
 static void Capture(Canvas canvas,BattleWorld world,string path){var target=new RenderTexture(1280,720,24);var camera=world.setup.mapCamera;var oldTarget=camera.targetTexture;int oldSorting=canvas.sortingOrder;canvas.sortingOrder=1000;var oldMode=canvas.renderMode;var oldCamera=canvas.worldCamera;canvas.renderMode=RenderMode.ScreenSpaceCamera;canvas.worldCamera=camera;canvas.planeDistance=1;camera.targetTexture=target;Canvas.ForceUpdateCanvases();camera.Render();var oldActive=RenderTexture.active;RenderTexture.active=target;var image=new Texture2D(1280,720,TextureFormat.RGB24,false);image.ReadPixels(new Rect(0,0,1280,720),0,0);image.Apply();File.WriteAllBytes(path,image.EncodeToPNG());RenderTexture.active=oldActive;camera.targetTexture=oldTarget;canvas.renderMode=oldMode;canvas.worldCamera=oldCamera;canvas.sortingOrder=oldSorting;UnityEngine.Object.DestroyImmediate(image);target.Release();UnityEngine.Object.DestroyImmediate(target);}
}






